# shot_stage.py — the USD stage of a shot, generated by FLUX (A4, ADR 0020).
#
#   <SHOT_path>/usd/<SEQ>_<SHOT>_vNNN/
#       <SEQ>_<SHOT>.usda            entry: fps, frame range, units, sublayers (strong -> weak)
#       <SEQ>_<SHOT>_animation.usda  one reference per animated character, onto its casting prim
#       <SEQ>_<SHOT>_casting.usda    /assets/<CLASS>/<NAME>_NN (components), /sets/<NAME> (decors)
#   <SHOT_path>/usd/<SEQ>_<SHOT>_LAST.usda   pointer (ADR 0017)
#
# Entry sublayers: lighting > fx > simulation > crowd > animation > layout > casting > <SEQ>.usda.
# FLUX decides WHAT is in the shot (Production casting, published departments, versions);
# the DCC decides WHERE (layout, animation, lights). Relative paths only (ADR 0010).

from __future__ import annotations

import json
import re
from pathlib import Path

from core.logger import get_logger

from .component_auto import COMPONENT_EXT, _rel, component_dir
from .structure.naming import sanitize_token

log = get_logger("usd_assembler.shot_stage")

STAGE_SUBDIR = "usd"
STAGE_EXT = ".usda"
USD_EXTS = (".usd", ".usda", ".usdc")
DEFAULT_CLASS = "ASSET"
ASSETS_ROOT = "assets"
SETS_ROOT = "sets"

# Shot TYPE -> (department, strength). ADR 0019 point 6 / ADR 0020 point 2.
# Variant set of a character animated in several ANIM sub-tasks (block / spline /
# polish, 2026-09-27): one variant per sub-task, the most advanced one selected.
# FLUX Shot Import lists it with the other variants of the asset.
ANIM_VARIANT_SET = "anim_subtask"
SUBTASK_PREFERENCE = ("POLISH", "SPLINE", "BLOCK")

SHOT_DEPARTMENTS: dict[str, tuple[str, int]] = {
    "LAYOUT": ("layout", 200),
    "ANIM": ("animation", 300),
    "CROWD": ("crowd", 350),          # A7 crowd layers (features/usd_assembler/crowd.py)
    "CFX": ("simulation", 400),
    "FX": ("fx", 500),
    "LIGHT": ("lighting", 600),
}


# ── locations ────────────────────────────────────────────────────────────────

def entity(seq: str, shot: str) -> str:
    return f"{seq.upper()}_{shot.upper()}"


def shot_dir(project_path: str | Path, seq: str, shot: str) -> Path:
    """``<project>/<SHOT token path>`` (``shot/SEQ001/SHOT010``), else ``<SEQ path>/<SHOT>``."""
    from features.folder_manager.tokens import load_tokens

    project = Path(project_path)
    tokens = load_tokens(project) or {}
    rel = (tokens.get("SHOT") or {}).get(f"{seq.upper()}/{shot.upper()}")
    if rel:
        return project / str(rel).replace("\\", "/")
    seq_rel = (tokens.get("SEQ") or {}).get(seq.upper())
    base = project / str(seq_rel).replace("\\", "/") if seq_rel else project / "shot" / seq.upper()
    return base / shot.upper()


def seq_dir(project_path: str | Path, seq: str) -> Path:
    from features.folder_manager.tokens import load_tokens

    project = Path(project_path)
    rel = ((load_tokens(project) or {}).get("SEQ") or {}).get(seq.upper())
    return project / str(rel).replace("\\", "/") if rel else project / "shot" / seq.upper()


def stage_dir(project_path: str | Path, seq: str, shot: str) -> Path:
    return shot_dir(project_path, seq, shot) / STAGE_SUBDIR


def last_file(project_path: str | Path, seq: str, shot: str) -> Path:
    return stage_dir(project_path, seq, shot) / f"{entity(seq, shot)}_LAST{STAGE_EXT}"


def stage_versions(project_path: str | Path, seq: str, shot: str) -> list[str]:
    parent, name = stage_dir(project_path, seq, shot), entity(seq, shot)
    rx = re.compile(rf"^{re.escape(name)}_(v\d+)$")
    out = [m.group(1) for p in (parent.iterdir() if parent.is_dir() else [])
           if (m := rx.match(p.name)) and p.is_dir() and (p / f"{name}{STAGE_EXT}").is_file()]
    return sorted(out, key=lambda v: int(v[1:]))


def _is_workspace_project(project: Path) -> bool:
    try:
        from core.paths import get_project_path

        return get_project_path(project.name).resolve() == project.resolve()
    except Exception:           # noqa: BLE001
        return False


def load_project_production(project: Path) -> tuple[dict, bool]:
    """(production, saved through the repository). A project outside the workspace (tests,
    another root) is read from its own production.json and never written back."""
    from features.production.production_store import default_schema, load_production

    if _is_workspace_project(project):
        return load_production(project.name), True
    path = project / "production.json"
    if path.is_file():
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            if isinstance(data, dict):
                return {**default_schema(), **data}, False
        except (OSError, ValueError):
            pass
    return default_schema(), False


# ── production casting ───────────────────────────────────────────────────────

def _find_seq(production: dict, seq: str) -> dict | None:
    return next((s for s in production.get("sequences", []) if s.get("name") == seq.upper()), None)


def _find_shot(production: dict, seq_entry: dict | None, shot: str) -> dict | None:
    if seq_entry is None:
        return None
    return next((s for s in production.get("shots", [])
                 if s.get("seq_id") == seq_entry.get("id") and s.get("name") == shot.upper()), None)


def _link_name(production: dict, link: dict) -> tuple[str, str] | None:
    """(CLASS, NAME) of a casting link ``{"id", "ref": "CLASS/NAME"}``."""
    asset = next((a for a in production.get("assets", []) if a.get("id") == link.get("id")), None)
    if asset is not None:
        return str(asset.get("class") or ""), str(asset.get("name") or "")
    ref = str(link.get("ref") or "")
    if "/" in ref:
        cls, name = ref.split("/", 1)
        return cls, name
    return ("", ref) if ref else None


def link_version(link: dict) -> str:
    """Pinned version of a casting link (ADR 0048): ``"vNNN"``, or ``""`` (follows LAST)."""
    raw = str(link.get("version") or "").strip()
    m = re.fullmatch(r"[vV](\d+)", raw)
    return f"v{m.group(1)}" if m else ""


def read_casting(production: dict, seq: str, shot: str) -> list[dict]:
    """Casting of a shot (ADR 0020 point 1): the sequence links (when the shot inherits)
    plus the shot's own, merged by asset. ``[{"class", "name", "count", "source", "version"}]``.

    ``version`` (ADR 0048): ``""`` follows LAST, ``"vNNN"`` pins it. A shot link that pins
    wins over the sequence's pin; a link without pin (old links, auto-cast) changes nothing."""
    seq_entry = _find_seq(production, seq)
    shot_entry = _find_shot(production, seq_entry, shot)
    links: list[tuple[dict, str]] = []
    if seq_entry is not None and (shot_entry is None or shot_entry.get("inherit_assets", True)):
        links += [(link, "sequence") for link in seq_entry.get("assets") or []]
    if shot_entry is not None:
        links += [(link, "shot") for link in shot_entry.get("assets") or []]
    out: dict[str, dict] = {}
    for link, source in links:
        named = _link_name(production, link)
        if not named or not named[1]:
            continue
        cls, name = named
        count = max(1, int(link.get("count") or 1))
        version = link_version(link)
        item = out.get(name.upper())
        if item is None:
            out[name.upper()] = {"class": cls.upper(), "name": name.upper(), "count": count,
                                 "source": source, "version": version}
        else:
            item["count"] = max(item["count"], count)
            # Links come sequence first, then shot: a later pin is the shot's, it wins.
            if version and (not item["version"] or source == "shot"):
                item["version"] = version
    return list(out.values())


def read_frame_range(production: dict, seq: str, shot: str) -> tuple[int, int] | None:
    shot_entry = _find_shot(production, _find_seq(production, seq), shot)
    if shot_entry is None:
        return None
    start, end = shot_entry.get("frame_start"), shot_entry.get("frame_end")
    try:
        if start is None or end is None or int(end) < int(start):
            return None
        return int(start), int(end)
    except (TypeError, ValueError):
        return None


def add_to_casting(production: dict, seq: str, shot: str, cls: str, name: str, count: int) -> bool:
    """Auto-cast an animated character on the shot (ADR 0020 point 3). True when changed.

    Only for an asset Production knows (a link needs its id)."""
    seq_entry = _find_seq(production, seq)
    shot_entry = _find_shot(production, seq_entry, shot)
    asset = next((a for a in production.get("assets", [])
                  if a.get("name") == name.upper() and (not cls or a.get("class") == cls.upper())), None)
    if shot_entry is None or asset is None:
        return False
    links = shot_entry.setdefault("assets", [])
    link = next((x for x in links if x.get("id") == asset["id"]), None)
    if link is None:
        links.append({"id": asset["id"], "ref": f"{asset.get('class')}/{asset.get('name')}",
                      "count": count, "origin": "auto"})
        return True
    if int(link.get("count") or 1) < count:
        link["count"] = count
        return True
    return False


# ── published layers ─────────────────────────────────────────────────────────

def _frozen(path: Path) -> Path:
    """The vNNN a LAST pointer targets (the file itself when it is not a pointer)."""
    from features.publisher.last_pointer import read_layer_flux

    if "_LAST" not in path.stem:
        return path
    target = (read_layer_flux(path) or {}).get("target")
    if target:
        cand = path.parent / target
        if cand.is_file():
            return cand
    return path


def _dept_dir(project: Path, tokens: dict, task: str, seq: str, shot: str) -> Path | None:
    rel = (tokens.get("TYPE_SHOT") or {}).get(task) or (tokens.get("CLASS") or {}).get(task)
    if not rel:
        return None
    try:
        return project / str(rel).replace("\\", "/").format(seq=seq.upper(), shot=shot.upper())
    except (KeyError, IndexError):
        return None


def department_files(project_path: str | Path, seq: str, shot: str, task: str) -> list[Path]:
    """LAST files of the shot publishes of TYPE *task* (``SEQ_SHOT_TYPE[_X]_LAST.usd*``)."""
    from features.folder_manager.tokens import load_tokens

    project = Path(project_path)
    folder = _dept_dir(project, load_tokens(project) or {}, task, seq, shot)
    if folder is None or not folder.is_dir():
        return []
    prefix = f"{entity(seq, shot)}_{task.upper()}".lower()
    found = []
    for sub in sorted(p for p in folder.iterdir() if p.is_dir()):
        for f in sorted(sub.iterdir()):
            stem = f.stem
            if (f.suffix.lower() in USD_EXTS and stem.endswith("_LAST")
                    and stem.lower().startswith(prefix) and ".proxy" not in f.name):
                found.append(f)
    return found


def _anim_instance(item: dict) -> str:
    """``DINGO`` -> ``DINGO_01``, ``DINGO_02`` -> ``DINGO_02`` (ADR 0020 point 3)."""
    name, character = item["name"].upper(), item["character"].upper()
    rest = character[len(name):].lstrip("_") if character.startswith(name) else ""
    if rest.isdigit():
        return f"{name}_{int(rest):02d}"
    return f"{name}_01" if not rest else sanitize_token(character)


def _variant_name(subtask: str) -> str:
    """USD variant name of an ANIM sub-task folder ("" -> "main")."""
    name = re.sub(r"[^A-Za-z0-9_]", "_", subtask.lower()) or "main"
    return name if not name[0].isdigit() else "v" + name


def _default_prim(path: Path) -> str:
    from features.publisher.last_pointer import read_usd_root_info

    return str(read_usd_root_info(path).get("defaultPrim") or "")


def _time_range(path: Path) -> tuple[float, float] | None:
    from features.publisher.last_pointer import read_usd_root_info

    info = read_usd_root_info(path)
    if "startTimeCode" in info and "endTimeCode" in info:
        return float(info["startTimeCode"]), float(info["endTimeCode"])
    return None


def _project_units(project: Path) -> dict:
    from features.folder_manager.project_config import read_project_config

    cfg = read_project_config(project) or {}
    usd = cfg.get("usd") or {}
    return {"fps": float(cfg.get("fps") or 24), "meters_per_unit": float(usd.get("meters_per_unit") or 1.0),
            "up_axis": str(usd.get("up_axis") or "Y")}


# ── plan ─────────────────────────────────────────────────────────────────────

def asset_versions(project: Path, name: str) -> list[str]:
    """Published versions ``vNNN`` of an asset's USD entry (component or assembly), oldest first."""
    from .assembly_v2 import assembly_versions

    parent = component_dir(project, name)
    return assembly_versions(parent, name) if parent is not None else []


def _asset_target(project: Path, name: str, version: str = "",
                  warnings: list[str] | None = None) -> tuple[str, Path, str] | None:
    """("component" | "assembly", entry, pinned version) of an asset's USD, or None.

    Without *version* the entry is ``<NAME>_LAST.usda`` (pinned ""). With ``"vNNN"``
    (ADR 0048) it is ``<NAME>_vNNN/<NAME>.usda``; a version not found falls back on LAST
    with a warning."""
    from .assembly_v2 import _entry_in, _kind_of, _version_entry

    parent = component_dir(project, name)
    if parent is None:
        return None
    last = parent / f"{name}_LAST{COMPONENT_EXT}"
    if version:
        # Match by number: "v3" and "v003" are the same version, the folder name is the truth.
        found = next((v for v in asset_versions(project, name) if int(v[1:]) == int(version[1:])), None)
        if found is not None:
            entry = _version_entry(parent, name, found)
            return (_kind_of(entry) or "component"), entry, found
        if warnings is not None:
            warnings.append(f"{name} : version epinglee {version} introuvable, suit LAST")
    if not last.is_file():
        return None
    kind = _kind_of(_entry_in(parent, name)) or "component"
    return kind, last, ""


def collect(project_path: str | Path, seq: str, shot: str, production: dict) -> dict:
    """What the shot stage holds, without writing anything.

    {"casting": [{"class", "name", "prim", "kind", "path", "version"}], "departments": [{"task",
    "department", "files"}], "anims": [{"character", "instance", "prim", "path"}],
    "range", "fps", "units", "auto_cast": [(class, name, count)], "warnings"}
    """
    from features.importer.shot_anim import list_shot_anims

    project = Path(project_path)
    warnings: list[str] = []
    units = _project_units(project)

    cast = read_casting(production, seq, shot)
    anims = [a for a in list_shot_anims(project)
             if a["seq"].upper() == seq.upper() and a["shot"].upper() == shot.upper() and a["last"]]

    # Animated characters that are not (or not enough times) in the casting: added.
    auto_cast: list[tuple[str, str, int]] = []
    by_name = {c["name"]: c for c in cast}
    from features.folder_manager.tokens import load_tokens

    from .library import _class_of

    tokens = load_tokens(project) or {}
    for item in anims:
        inst = _anim_instance(item)
        m = re.search(r"_(\d+)$", inst)
        needed = int(m.group(1)) if m else 1
        name = item["name"].upper()
        entry = by_name.get(name)
        if entry is None:
            cls = _class_of(tokens, item["name"]) or DEFAULT_CLASS
            entry = by_name[name] = {"class": cls, "name": name, "count": needed, "source": "anim"}
            cast.append(entry)
            auto_cast.append((cls, name, needed))
            warnings.append(f"{inst} : anim publiee, perso ajoute au casting")
        elif entry["count"] < needed:
            entry["count"] = needed
            auto_cast.append((entry["class"], name, needed))
            warnings.append(f"{inst} : anim publiee, instance ajoutee au casting")

    casting: list[dict] = []
    for c in cast:
        target = _asset_target(project, c["name"], c.get("version") or "", warnings)
        if target is None:
            warnings.append(f"{c['name']} : pas d'USD d'asset (component) publie, ignore")
            continue
        kind, path, version = target
        if kind == "assembly":
            casting.append({"class": c["class"], "name": c["name"], "kind": kind,
                            "prim": f"/{SETS_ROOT}/{sanitize_token(c['name'])}", "path": path,
                            "version": version})
            continue
        cls = sanitize_token(c["class"]) or DEFAULT_CLASS
        # Every _NN instance of an asset shares the pinned version (ADR 0048).
        for n in range(1, c["count"] + 1):
            casting.append({"class": cls, "name": c["name"], "kind": kind,
                            "prim": f"/{ASSETS_ROOT}/{cls}/{sanitize_token(c['name'])}_{n:02d}",
                            "path": path, "version": version})

    anim_items: list[dict] = []
    by_inst: dict[str, dict] = {}
    for item in anims:
        inst = _anim_instance(item)
        target = next((c for c in casting if c["prim"].rsplit("/", 1)[-1] == inst), None)
        if target is None:
            warnings.append(f"{item['base']} : aucun perso {inst} dans le stage, anim ignoree")
            continue
        path = Path(item["last"])
        variant = {"path": path, "source_prim": _default_prim(path) or item["name"]}
        entry = by_inst.get(inst)
        if entry is None:
            entry = by_inst[inst] = {"character": item["character"], "instance": inst,
                                     "prim": target["prim"], "variants": {}}
            anim_items.append(entry)
        entry["variants"][_variant_name(item.get("subtask") or "")] = variant
    for entry in anim_items:
        # The default (selected) variant: the most advanced sub-task published.
        names = list(entry["variants"])
        chosen = next((n for pref in SUBTASK_PREFERENCE for n in names if n == pref.lower()),
                      sorted(names)[0])
        entry.update(entry["variants"][chosen], default=chosen, range=_time_range(entry["variants"][chosen]["path"]))
        if len(names) == 1:
            entry["variants"] = {}          # one sub-task: a plain reference, no variant set

    departments: list[dict] = []
    for task, (dept, _strength) in sorted(SHOT_DEPARTMENTS.items(), key=lambda kv: -kv[1][1]):
        if task == "ANIM":
            continue            # per character, see anim_items
        files = department_files(project, seq, shot, task)
        if len(files) > 1:
            warnings.append(f"{dept} : {len(files)} publishs, tous empiles (le premier gagne)")
        departments.append({"task": task, "department": dept, "files": files})

    frame_range = read_frame_range(production, seq, shot)
    anim_ranges = [a["range"] for a in anim_items if a["range"]]
    if frame_range is None:
        if anim_ranges:
            frame_range = (int(min(r[0] for r in anim_ranges)), int(max(r[1] for r in anim_ranges)))
            warnings.append("plage du shot non saisie dans Production : plage des anims publiees")
        else:
            warnings.append("plage du shot non saisie dans Production")
    else:
        for a in anim_items:
            r = a["range"]
            if r and (r[0] < frame_range[0] or r[1] > frame_range[1]):
                warnings.append(f"anim {a['instance']} ({int(r[0])}-{int(r[1])}) hors de la plage du shot "
                                f"({frame_range[0]}-{frame_range[1]})")
    if not any(d["files"] for d in departments if d["task"] == "LAYOUT"):
        warnings.append("pas de layout publie : pas de camera")
    if not casting:
        warnings.append("casting vide : rien a charger dans le shot")

    return {"casting": casting, "departments": departments, "anims": anim_items,
            "range": frame_range, "fps": units["fps"], "units": units,
            "auto_cast": auto_cast, "warnings": warnings}


# ── authoring ────────────────────────────────────────────────────────────────

def _shot_light_template(project: Path, seq: str, shot: str) -> Path | None:
    cand = stage_dir(project, seq, shot) / "lighting" / f"{entity(seq, shot)}_light.usda"
    return cand if cand.is_file() else None


def _seq_root(project: Path, seq: str) -> Path | None:
    cand = seq_dir(project, seq) / STAGE_SUBDIR / f"{seq.upper()}.usda"
    return cand if cand.is_file() else None


def _layer_list(project: Path, seq: str, shot: str, plan: dict, folder: Path,
                frozen: bool) -> list[tuple[str, str]]:
    """[(role, relative path)] of the entry sublayers, strong -> weak."""
    def rel(p: Path) -> str:
        return _rel(_frozen(p) if frozen else p, folder)

    name = entity(seq, shot)
    out: list[tuple[str, str]] = []
    for dept in plan["departments"]:
        if dept["task"] == "LAYOUT":
            continue
        if dept["files"]:
            out += [(dept["department"], rel(f)) for f in dept["files"]]
        elif dept["task"] == "LIGHT":
            tpl = _shot_light_template(project, seq, shot)
            if tpl is not None:
                out.append(("lighting", _rel(tpl, folder)))
    if plan["anims"]:
        out.append(("animation", f"./{name}_animation{STAGE_EXT}"))
    layout = next(d for d in plan["departments"] if d["task"] == "LAYOUT")
    out += [("layout", rel(f)) for f in layout["files"]]
    out.append(("casting", f"./{name}_casting{STAGE_EXT}"))
    root = _seq_root(project, seq)
    if root is not None:
        out.append(("sequence", _rel(root, folder)))
    # The strongest sublayer comes first: keep the lighting > fx > simulation order.
    order = {"lighting": 0, "fx": 1, "simulation": 2, "crowd": 3, "animation": 4, "layout": 5,
             "casting": 6, "sequence": 7}
    return sorted(out, key=lambda kv: order.get(kv[0], 9))


def signature(project_path: str | Path, seq: str, shot: str, plan: dict, *, frozen: bool = False) -> dict:
    """What makes two versions identical (paths relative to a version folder)."""
    project = Path(project_path)
    folder = stage_dir(project, seq, shot) / f"{entity(seq, shot)}_v000"

    def rel(p: Path) -> str:
        return _rel(_frozen(p) if frozen else p, folder)

    return {
        "layers": [list(x) for x in _layer_list(project, seq, shot, plan, folder, frozen)],
        "casting": [[c["prim"], rel(c["path"])] for c in plan["casting"]],
        "anims": [[a["prim"], rel(a["path"]), a["source_prim"]]
                  + ([[a["default"]] + [[n, rel(v["path"]), v["source_prim"]]
                                        for n, v in sorted(a["variants"].items())]]
                     if a.get("variants") else [])
                  for a in plan["anims"]],
        "range": list(plan["range"]) if plan["range"] else None,
        "fps": plan["fps"],
        "frozen": frozen,
    }


def _author(folder: Path, project: Path, seq: str, shot: str, version: str, plan: dict,
            sig: dict, frozen: bool) -> Path:
    from pxr import Sdf

    folder.mkdir(parents=True, exist_ok=True)
    name = entity(seq, shot)

    def rel(p: Path) -> str:
        return _rel(_frozen(p) if frozen else p, folder)

    # 1. casting: who is in the shot.
    casting_path = folder / f"{name}_casting{STAGE_EXT}"
    casting = Sdf.Layer.CreateNew(str(casting_path))
    roots: dict[str, Sdf.PrimSpec] = {}
    groups: dict[str, Sdf.PrimSpec] = {}
    for c in plan["casting"]:
        parts = c["prim"].strip("/").split("/")
        top = roots.get(parts[0])
        # kind=group on /assets, /assets/<CLASS>, /sets: the model hierarchy must be
        # contiguous up to the root, else the components below are not models for USD
        # (Houdini kind selection, model traversals, bbox caches ignore them). R1.
        if top is None:
            top = roots[parts[0]] = Sdf.PrimSpec(casting, parts[0], Sdf.SpecifierDef, "Scope")
            top.kind = "group"
        parent = top
        if len(parts) == 3:
            key = "/".join(parts[:2])
            parent = groups.get(key)
            if parent is None:
                parent = groups[key] = Sdf.PrimSpec(top, parts[1], Sdf.SpecifierDef, "Scope")
                parent.kind = "group"
        # Typeless: the component's root type (SkelRoot for a character) comes through.
        prim = Sdf.PrimSpec(parent, parts[-1], Sdf.SpecifierDef)
        prim.kind = "component" if c["kind"] == "component" else "assembly"
        prim.referenceList.prependedItems = [Sdf.Reference(rel(c["path"]))]
        if c.get("version"):
            # Readable trace of the pin (ADR 0048); the reference path is what composes.
            prim.SetInfo("customData", {"flux": {"pinned_version": c["version"]}})
    casting.Save()

    # 2. animation: each character's motion referenced onto its casting prim.
    if plan["anims"]:
        anim_path = folder / f"{name}_animation{STAGE_EXT}"
        anim = Sdf.Layer.CreateNew(str(anim_path))
        for a in plan["anims"]:
            spec = Sdf.CreatePrimInLayer(anim, Sdf.Path(a["prim"]))    # "over" all the way down
            if not a.get("variants"):
                spec.referenceList.prependedItems = [
                    Sdf.Reference(rel(a["path"]), Sdf.Path(f"/{a['source_prim']}"))]
                continue
            # Several sub-tasks: one variant each, the most advanced selected.
            vset = Sdf.VariantSetSpec(spec, ANIM_VARIANT_SET)
            spec.variantSetNameList.prependedItems = [ANIM_VARIANT_SET]
            for vname, v in sorted(a["variants"].items()):
                var = Sdf.VariantSpec(vset, vname)
                var.primSpec.referenceList.prependedItems = [
                    Sdf.Reference(rel(v["path"]), Sdf.Path(f"/{v['source_prim']}"))]
            spec.variantSelections[ANIM_VARIANT_SET] = a["default"]
        anim.Save()

    # 3. entry: time, units, sublayers.
    entry_path = folder / f"{name}{STAGE_EXT}"
    entry = Sdf.Layer.CreateNew(str(entry_path))
    entry.subLayerPaths[:] = [p for _role, p in _layer_list(project, seq, shot, plan, folder, frozen)]
    units = plan["units"]
    entry.framesPerSecond = plan["fps"]
    entry.timeCodesPerSecond = plan["fps"]
    if plan["range"]:
        entry.startTimeCode, entry.endTimeCode = float(plan["range"][0]), float(plan["range"][1])
    root = entry.pseudoRoot
    root.SetInfo("metersPerUnit", units["meters_per_unit"])
    root.SetInfo("upAxis", units["up_axis"])
    entry.customLayerData = {"flux": {
        "role": "shot_stage", "sequence": seq.upper(), "shot": shot.upper(), "version": version,
        "frozen": bool(frozen),
        # A JSON string: USD dictionaries cannot hold lists of lists.
        "signature_json": json.dumps(sig, sort_keys=True),
    }}
    entry.Save()
    return entry_path


def _latest_signature(project: Path, seq: str, shot: str) -> dict | None:
    versions = stage_versions(project, seq, shot)
    if not versions:
        return None
    from pxr import Sdf

    name = entity(seq, shot)
    layer = Sdf.Layer.OpenAsAnonymous(
        str(stage_dir(project, seq, shot) / f"{name}_{versions[-1]}" / f"{name}{STAGE_EXT}"))
    flux = dict(layer.customLayerData).get("flux", {}) if layer is not None else {}
    try:
        return json.loads(flux.get("signature_json") or "null")
    except ValueError:
        return None


def write_stage(project_path: str | Path, seq: str, shot: str, *, production: dict | None = None,
                user: str = "", frozen: bool = False, save_casting: bool = True) -> dict:
    """(Re)generate the shot stage. A new version is written only when something changed.

    Returns {"version" (None when unchanged), "entry", "last", "plan", "warnings",
    "auto_cast"}. *production* defaults to the project's production.json; animated
    characters missing from the casting are saved back into it (*save_casting*).
    """
    from features.folder_manager.naming_validator import format_version
    from features.publisher import last_pointer as lp
    from features.publisher.publish_layout import (
        discard_rendered_version, reserve_version, sequence_folder,
    )

    project = Path(project_path)
    seq, shot = seq.upper(), shot.upper()
    own_production = production is None
    can_save = False
    if own_production:
        production, can_save = load_project_production(project)
    # ADR 0038: no shot light layer is made any more (an old one still found is sublayered).
    plan = collect(project, seq, shot, production)

    saved_cast = []
    if plan["auto_cast"]:
        for cls, name, count in plan["auto_cast"]:
            if add_to_casting(production, seq, shot, cls, name, count):
                saved_cast.append(name)
        if saved_cast and own_production and can_save and save_casting:
            from features.production.production_store import save_production

            save_production(project.name, production)

    sig = signature(project, seq, shot, plan, frozen=frozen)
    parent = stage_dir(project, seq, shot)
    name = entity(seq, shot)
    out = {"version": None, "entry": None, "last": last_file(project, seq, shot), "plan": plan,
           "warnings": plan["warnings"], "auto_cast": saved_cast}
    if _latest_signature(project, seq, shot) == sig:
        versions = stage_versions(project, seq, shot)
        if versions:
            out["entry"] = parent / f"{name}_{versions[-1]}" / f"{name}{STAGE_EXT}"
        return out

    ver = reserve_version(parent, name, STAGE_EXT)
    folder = sequence_folder(parent, name, ver)
    version = format_version(ver)
    try:
        entry = _author(folder, project, seq, shot, version, plan, sig, frozen)
    except Exception:
        discard_rendered_version(parent, name, STAGE_EXT, ver, is_sequence=True)
        raise
    last = lp.write_last(parent, name, STAGE_EXT, folder, ver, lp.MODE_LAYER, user=user,
                         layer_target=f"{folder.name}/{entry.name}")
    _retire_template_root(project, parent / f"{name}{STAGE_EXT}")
    from features.publisher.modif_log import append_log

    what = ", ".join(sorted({c["name"] for c in plan["casting"]})) or "casting vide"
    append_log(parent, name, version,
               ("stage fige : " if frozen else "stage du shot regenere : ") + what, user or "flux")
    log.info("Shot stage %s %s -> %s", name, version, folder)
    out.update(version=version, entry=entry, last=last)
    return out


def _retire_template_root(project: Path, legacy: Path) -> None:
    """The old template root <SEQ>_<SHOT>.usda (written by FLUX, role shot_root) is replaced
    by the stage: move it to <project>/_backup_flux/<date>/ (2026-09-19: one layout per shot)."""
    if not legacy.is_file():
        return
    try:
        from datetime import datetime

        from features.publisher.last_pointer import read_layer_flux

        if (read_layer_flux(legacy) or {}).get("role") != "shot_root":
            return
        dest = project / "_backup_flux" / datetime.now().strftime("%Y%m%d-%H%M%S") / legacy.relative_to(project)
        dest.parent.mkdir(parents=True, exist_ok=True)
        legacy.replace(dest)
        log.info("Old shot root %s moved to %s", legacy.name, dest.parent)
    except Exception as exc:     # noqa: BLE001 - cosmetic cleanup, never fails a stage
        log.warning("Old shot root %s kept: %s", legacy.name, exc)


def refresh_from_publish_folder(dest_folder: str | Path, base: str, ext: str, *,
                                user: str = "") -> dict | None:
    """Publish hook: a USD publish of a shot department regenerates the shot stage.
    Never raises."""
    if str(ext).lower() not in USD_EXTS:
        return None
    try:
        from features.folder_manager.naming_validator import parse_filename

        parsed = parse_filename(f"{base}.usd")
        if not parsed or not parsed.get("is_shot"):
            return None
        task = str(parsed.get("TYPE") or parsed.get("CLASS") or "").upper()
        if task not in SHOT_DEPARTMENTS:
            return None
        folder = Path(dest_folder).resolve()
        project = next((p for p in [folder, *folder.parents] if (p / "tokens.json").is_file()), None)
        if project is None:
            return None
        return write_stage(project, parsed["SEQ"], parsed["SHOT"], user=user)
    except Exception as exc:     # noqa: BLE001 - a stage failure never fails a publish
        log.warning("Shot stage refresh failed for %s: %s", base, exc)
        return None


# ── reading (UI) ─────────────────────────────────────────────────────────────

def list_shots(project_path: str | Path, production: dict | None = None) -> list[dict]:
    """Every shot of Production (plus shots that already have a stage), for the USD page."""
    project = Path(project_path)
    if production is None:
        production, _ = load_project_production(project)
    seqs = {s.get("id"): s.get("name") for s in production.get("sequences", [])}
    items = []
    for sh in production.get("shots", []):
        seq = seqs.get(sh.get("seq_id"))
        if not seq:
            continue
        items.append(shot_summary(project, seq, sh["name"], production))
    return sorted(items, key=lambda i: (i["seq"], i["shot"]))


def shot_summary(project_path: str | Path, seq: str, shot: str, production: dict) -> dict:
    from features.publisher.publish_layout import last_version_label

    project = Path(project_path)
    seq, shot = seq.upper(), shot.upper()
    plan = collect(project, seq, shot, production)
    parent = stage_dir(project, seq, shot)
    name = entity(seq, shot)
    versions = stage_versions(project, seq, shot)
    last = last_file(project, seq, shot)
    latest = _latest_signature(project, seq, shot)
    current = signature(project, seq, shot, plan)
    frozen = bool(latest and latest.get("frozen"))
    state = "none" if not versions else ("frozen" if frozen else
                                         ("up_to_date" if latest == current else "outdated"))
    legacy = parent / f"{name}{STAGE_EXT}"
    newest: dict[str, str] = {}

    def _newest(asset: str) -> str:
        if asset not in newest:
            newest[asset] = (asset_versions(project, asset) or [""])[-1]
        return newest[asset]

    return {
        "seq": seq, "shot": shot, "entity": name, "state": state,
        "versions": versions,
        "last_version": last_version_label(parent, name, STAGE_EXT) if last.is_file() else None,
        "last": str(last) if last.is_file() else None,
        # Project-relative (forward slashes): what "Ouvrir dans Houdini" sends to the importer.
        "rel_last": last.relative_to(project).as_posix() if last.is_file() else None,
        "legacy": str(legacy) if legacy.is_file() else None,
        # version: pinned "vNNN" or "" (LAST); latest_version: newest published (ADR 0048).
        "casting": [{"prim": c["prim"], "name": c["name"], "kind": c["kind"],
                     "version": c.get("version") or "",
                     "latest_version": _newest(c["name"])}
                    for c in plan["casting"]],
        "anims": [{"instance": a["instance"], "character": a["character"], "prim": a["prim"],
                   "range": list(a["range"]) if a["range"] else None} for a in plan["anims"]],
        "departments": [{"department": d["department"], "task": d["task"],
                         "files": [str(f) for f in d["files"]]} for d in plan["departments"]],
        "range": list(plan["range"]) if plan["range"] else None,
        "fps": plan["fps"],
        "warnings": plan["warnings"],
    }
